{"script": "python3 << 'EOF'
import FreeCAD
import Part

# Open the precondition file
doc = FreeCAD.open("/home/user/Precondition_Unnamed.FCStd")

# List all objects in the document
print("Objects in document:")
for obj in doc.Objects:
    print(f"  - {obj.Name}: {obj.Label} (Type: {obj.TypeId})")

# Look for sketches
for obj in doc.Objects:
    if "Sketch" in obj.TypeId:
        print(f"\nSketch found: {obj.Name}")
        # Try to get sketch geometry info
        try:
            if hasattr(obj, 'Geometry'):
                print(f"  Geometry count: {len(obj.Geometry)}")
                for i, geom in enumerate(obj.Geometry):
                    print(f"    Geometry {i}: {geom.TypeId}")
                    if hasattr(geom, 'Vertexes'):
                        print(f"      Vertexes: {len(geom.Vertexes)}")
        except Exception as e:
            print(f"  Error getting geometry: {e}")

# Check for PartDesign bodies
for obj in doc.Objects:
    if "Body" in obj.TypeId:
        print(f"\nBody found: {obj.Name}")
        print(f"  Label: {obj.Label}")

FreeCAD.close(doc)
EOF
